import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createOrder} from '../src/order.mjs';
import {shippingFee} from '../src/shipping.mjs';

test('hidden check', async () => {
  assert.equal(createOrder({items: [{price: 1000, quantity: 1}], grade: 'vip'}).shipping, 0);
  assert.equal(createOrder({items: [{price: 1000, quantity: 1}], grade: 'vip', region: 'jeju'}).shipping, 4500);
  assert.equal(createOrder({items: [{price: 1000, quantity: 1}], grade: 'gold'}).shipping, 3000);
  assert.equal(shippingFee(1000, 'seoul'), 3000);
});
